import sailpoint.object.Bundle;
import sailpoint.tools.Util;

boolean isSuccess = false;

Set detected = new HashSet(identity.getDetectedRoles());
if (Util.isEmpty(detected)) {
  return isSuccess; // false, no detected roles
}

Bundle bizRole = context.getObjectByName(Bundle.class, roleName);
if (bizRole == null) {
  log.warn(roleName + " was not found... weird!");
  return isSuccess; // false, bad state
}

Set requirements = new HashSet(bizRole.getRequirements());
if (Util.isEmpty(requirements)) {
  return isSuccess; // false, no requirements
}

detected.retainAll(requirements);

// if there's anything left in detected, we have an intersection of required roles and detected roles. Yay!
isSuccess = !Util.isEmpty(detected);

return isSuccess;
